--
-- Table structure for table `vehicles`
--

DROP TABLE IF EXISTS `vehicles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vehicles` (
  `vehicle_id` int NOT NULL AUTO_INCREMENT,
  `plate_number` varchar(20) NOT NULL,
  `owner_name` varchar(100) DEFAULT NULL,
  `vehicle_type` enum('Car','Motorcycle','SUV','Truck') NOT NULL,
  `brand` varchar(50) DEFAULT NULL,
  `model` varchar(50) DEFAULT NULL,
  `time_in` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `time_out` datetime DEFAULT NULL,
  `slot_id` varchar(5) DEFAULT NULL,
  `duration` int DEFAULT NULL,
  `contact` varchar(50) DEFAULT NULL,
  `color` varchar(30) DEFAULT NULL,
  `payment` double DEFAULT NULL,
  `status` varchar(20) DEFAULT 'ACTIVE',
  `deleted` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`vehicle_id`),
  UNIQUE KEY `plate_number` (`plate_number`),
  KEY `fk_slot_id` (`slot_id`),
  CONSTRAINT `fk_slot_id` FOREIGN KEY (`slot_id`) REFERENCES `slots` (`slot_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=587 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

